See https://github.com/LLK/scratch-paint/issues/13 */

$ui-pane-border: #D9D9D9;
$ui-pane-gray: #F9F9F9;
$ui-background-blue: #e8edf1;

$text-primary: #575e75;

$looks-secondary: #855CD6;
$looks-transparent: hsla(260, 60%, 60%, 0.35); /* 35% transparent version of looks-secondary */

$red-primary: #FF661A;
$red-tertiary: #E64D00;

$sound-primary: #CF63CF;
$sound-tertiary: #A63FA6;

$control-primary: #FFAB19;

$data-primary: #FF8C1A;

$form-border: #E9EEF2;
/* DO NOT EDIT
@todo This file is copied from GUI and should be pulled out into a shared library.
See https://github.com/LLK/scratch-paint/issues/13 */

/* ACTUALLY, THIS IS EDITED ;)
THIS WAS CHANGED ON 10/25/2017 BY @mewtaylor TO ADD A VARIABLE FOR THE SMALLEST
GRID UNITS.

ALSO EDITED ON 11/13/2017 TO ADD IN CONTANTS FOR LAYOUT FROM `layout-contents.js`*/

$space: 0.5rem;
$grid-unit: .25rem;

$sprites-per-row: 5;

$menu-bar-height: 3rem;
$sprite-info-height: 6rem;
$stage-menu-height: 2.75rem;

$library-header-height: 4.375rem;

$form-radius: calc($space / 2);

/* layout contants from `layout-constants.js`, minus 1px */
$full-size: 1095px;
$full-size-paint: 1256px;
@import "../../css/colors.css";
@import "../../css/units.css";

.mod-menu-item {
    display: flex;
    margin: 0 -$grid-unit;
    min-width: 6.25rem;
    padding: calc(2 * $grid-unit);
    padding-left: calc(3 * $grid-unit);
    padding-right: calc(3 * $grid-unit);
    white-space: nowrap;
    width: 8.5rem;
    cursor: pointer;
    transition: 0.1s ease;
    align-items: center;
}

.mod-menu-item:hover {
    background: $looks-secondary;
    color: white;
}

.mod-context-menu {
    display: flex;
    flex-direction: column;
}

.mod-unselect {
    user-select: none;
}

.displayed-font-name {
    font-size: .8rem;
}

.font-dropdown {
    align-items: center;
    color: $text-primary;
    display: flex;
    font-size: 1rem;
    justify-content: space-between;
    width: 8.5rem;
    height: 2rem;
}

.serif {
    font-family: 'Serif';
}

.sans-serif {
    font-family: 'Sans Serif';
}

.serif {
    font-family: 'Serif';
}

.handwriting {
    font-family: 'Handwriting';
}

.marker {
    font-family: 'Marker';
}

.curly {
    font-family: 'Curly';
}

.pixel {
    font-family: 'Pixel';
}

.chinese {
    font-family: "Microsoft YaHei", "微软雅黑", STXihei, "华文细黑";
}

.japanese {
    font-family: "ヒラギノ角ゴ Pro W3", "Hiragino Kaku Gothic Pro", Osaka, "メイリオ", Meiryo, "ＭＳ Ｐゴシック", "MS PGothic";
}

.korean {
    font-family: "Malgun Gothic";
}
